export type Mutation = {
  __typename?: 'Mutation'
  /**
   * Attach an existing person to a field context (HAS_PERSON). This is the ONLY
   * write path for HAS_PERSON through GraphQL — the nested CONNECT on
   * FieldContext.people / Person.contexts is disabled.
   *
   * Authorization (enforced server-side in the resolver, not via @authorization):
   * the caller must be able to edit the context (owner, ADMIN, or MEMBER of its
   * parent Space — GUESTs are view-only), and a target carrying the `User` label
   * may only be attached when they are the caller themselves or already own / are
   * a member of that parent Space. Attaching a person unlocks their gated PII to
   * the space's members (Person contexts_SOME READ branch), so for registered
   * accounts, presence in the Space is the consent boundary. Non-user people
   * (PersonPulse / imported contacts) are space content and attachable by any
   * editor. Writes an activity Log.
   */
  addPersonToFieldContext: AddPersonToFieldContextResponse
  /**
   * Add a member to a space with a specific role.
   * Only the space owner or members with ADMIN role can add new members.
   */
  addSpaceMember: AddSpaceMemberResponse
  createAddPersonToFieldContextResponses: CreateAddPersonToFieldContextResponsesMutationResponse
  createAddSpaceMemberResponses: CreateAddSpaceMemberResponsesMutationResponse
  createCarePulses: CreateCarePulsesMutationResponse
  createChatbotResponses: CreateChatbotResponsesMutationResponse
  createCoreValuePulses: CreateCoreValuePulsesMutationResponse
  createCreateLogResponses: CreateCreateLogResponsesMutationResponse
  createCreatePersonConnectionResponses: CreateCreatePersonConnectionResponsesMutationResponse
  createDeleteDocumentResponses: CreateDeleteDocumentResponsesMutationResponse
  createDeletePersonConnectionResponses: CreateDeletePersonConnectionResponsesMutationResponse
  createDocumentIngestThreads: CreateDocumentIngestThreadsMutationResponse
  createDocuments: CreateDocumentsMutationResponse
  createFieldContexts: CreateFieldContextsMutationResponse
  createGoalPulses: CreateGoalPulsesMutationResponse
  createIngestDocumentResponses: CreateIngestDocumentResponsesMutationResponse
  createLogs: CreateLogsMutationResponse
  createMarkNotificationResponses: CreateMarkNotificationResponsesMutationResponse
  createPeople: CreatePeopleMutationResponse
  /**
   * Create or update a direct person-to-person connection.
   * Persists a CONNECTED_TO relationship with optional why/interests metadata.
   */
  createPersonConnection: CreatePersonConnectionResponse
  createPersonConnectionEdges: CreatePersonConnectionEdgesMutationResponse
  createRemoveSpaceMemberResponses: CreateRemoveSpaceMemberResponsesMutationResponse
  createResonanceLinks: CreateResonanceLinksMutationResponse
  createResourcePulses: CreateResourcePulsesMutationResponse
  createSpaceMemberships: CreateSpaceMembershipsMutationResponse
  createStoryPulses: CreateStoryPulsesMutationResponse
  createSubmitAssistantFeedbackResponses: CreateSubmitAssistantFeedbackResponsesMutationResponse
  createUpdatePersonConnectionResponses: CreateUpdatePersonConnectionResponsesMutationResponse
  createUpdatePersonPulseResponses: CreateUpdatePersonPulseResponsesMutationResponse
  createUpdateSpaceMemberRoleResponses: CreateUpdateSpaceMemberRoleResponsesMutationResponse
  createUpdateUserAiResponses: CreateUpdateUserAiResponsesMutationResponse
  createWeSpaces: CreateWeSpacesMutationResponse
  deleteAddPersonToFieldContextResponses: DeleteInfo
  deleteAddSpaceMemberResponses: DeleteInfo
  deleteCarePulses: DeleteInfo
  deleteChatbotResponses: DeleteInfo
  deleteCoreValuePulses: DeleteInfo
  deleteCreateLogResponses: DeleteInfo
  deleteCreatePersonConnectionResponses: DeleteInfo
  deleteDeleteDocumentResponses: DeleteInfo
  deleteDeletePersonConnectionResponses: DeleteInfo
  /**
   * Delete a Document and its backing blob. Caller must hold canEditContent
   * on the FieldContext's parent Space.
   *
   * Previously extracted entities (Persons, FieldPulses) survive — their
   * EXTRACTED_FROM edges drop with the Document but the entities remain in
   * the graph as user data (see PRD § Out of Scope — Documents never cascade
   * to their extractions).
   */
  deleteDocument: DeleteDocumentResponse
  deleteDocumentIngestThreads: DeleteInfo
  deleteDocuments: DeleteInfo
  deleteFieldContexts: DeleteInfo
  deleteGoalPulses: DeleteInfo
  deleteIngestDocumentResponses: DeleteInfo
  deleteLogs: DeleteInfo
  deleteMarkNotificationResponses: DeleteInfo
  deleteMeSpaces: DeleteInfo
  deletePeople: DeleteInfo
  /**
   * Delete a person-to-person connection.
   * Removes the CONNECTED_TO relationship between two people.
   */
  deletePersonConnection: DeletePersonConnectionResponse
  deletePersonConnectionEdges: DeleteInfo
  deleteRemoveSpaceMemberResponses: DeleteInfo
  deleteResonanceLinks: DeleteInfo
  deleteResourcePulses: DeleteInfo
  deleteSpaceMemberships: DeleteInfo
  deleteStoryPulses: DeleteInfo
  deleteSubmitAssistantFeedbackResponses: DeleteInfo
  deleteUpdatePersonConnectionResponses: DeleteInfo
  deleteUpdatePersonPulseResponses: DeleteInfo
  deleteUpdateSpaceMemberRoleResponses: DeleteInfo
  deleteUpdateUserAiResponses: DeleteInfo
  deleteUsers: DeleteInfo
  deleteWeSpaces: DeleteInfo
  /**
   * Generate embeddings for a person's profile.
   * Legacy mutation preserved for compatibility.
   */
  generatePersonEmbeddings: Scalars['Boolean']['output']
  /**
   * Invite someone to a space by email address, even if they are not yet a
   * GoalPost member. If no Person with that email exists, a placeholder Person
   * is created and a single-use invite email is sent so they can set a password
   * and join. If the email already belongs to a Person/User, they are added like
   * addSpaceMember. Only the space owner or members with ADMIN role can invite.
   */
  inviteToSpaceByEmail: AddSpaceMemberResponse
  /**
   * Log a field context-related activity (create, update, delete).
   * Tracks field context operations within spaces.
   */
  logFieldActivity: CreateLogResponse
  /**
   * Log a member-related activity (added, removed, role-changed).
   * Captures membership changes in spaces with role information.
   */
  logMemberActivity: CreateLogResponse
  /**
   * Log a pulse-related activity (create, update, delete).
   * Automatically creates a Log node with CREATED_BY relationship to the current user
   * and LOGGED_FOR relationship to the pulse.
   *
   * Example:
   *   mutation {
   *     logPulseActivity(input: {
   *       action: "created"
   *       pulseId: "pulse_123"
   *       pulseType: "GoalPulse"
   *       pulseName: "Launch MVP"
   *       contextId: "context_456"
   *     }) {
   *       success
   *       message
   *       log { id description createdAt }
   *     }
   *   }
   */
  logPulseActivity: CreateLogResponse
  /**
   * Log a resonance-related activity (created, updated, deleted).
   * Tracks AI-discovered or user-created resonance links between pulses.
   */
  logResonanceActivity: CreateLogResponse
  /**
   * Log a space-related activity (create, update, delete).
   * Creates a Log node with description and metadata about the space operation.
   */
  logSpaceActivity: CreateLogResponse
  /**
   * Mark all of the current user's notifications read. Recipient-scoped via the
   * JWT user id. Returns the new unread count (0).
   */
  markAllNotificationsRead: MarkNotificationResponse
  /**
   * Mark a single notification read. No-op if already read or not owned by the
   * caller. Recipient-scoped: only the notification's recipient may mark it (the
   * resolver re-checks the JWT user id, and the recipient MATCH is the auth gate).
   * Does NOT write to the activity Log stream. Returns the caller's fresh unread
   * count.
   */
  markNotificationRead: MarkNotificationResponse
  /**
   * Re-run the extraction model against an existing Document (slice 6 of
   * GOAL-235). The original blob is reused; no new blob is written, no new
   * Document node is created. A fresh ConversationThread titled
   * `Ingest: <filename> (re-extracted)` is created and linked back to the
   * Document via HAS_INGEST_THREAD so the Document detail view can list every
   * attempt.
   *
   * Caller must hold canEditContent on the FieldContext's parent Space.
   * Previously approved entities are untouched — re-extract only proposes
   * new tool calls.
   */
  reExtractDocument: IngestDocumentResponse
  /**
   * Remove a member from a space.
   * Only the space owner or members with ADMIN role can remove members.
   * Cannot remove the space owner.
   */
  removeSpaceMember: RemoveSpaceMemberResponse
  /** Send a message to the chatbot and receive a response. */
  sendMessageToChatbot?: Maybe<ChatbotResponse>
  /**
   * Persist a user-driven rating on a single assistant turn.
   *
   * Authorization:
   *   - The submitting user MUST own the ConversationThread containing the
   *     turn (enforced server-side; mismatch returns success:false).
   *
   * Inputs:
   *   - turnId:      the `ConversationTurn.id` exposed to the UI via the
   *                   AI SDK message metadata stream.
   *   - rating:      POSITIVE for thumbs-up, NEGATIVE for thumbs-down.
   *   - userComment: optional "what would have been better" text shown to
   *                   devs in the /dev/ai-quality triage dashboard.
   *
   * Auto-detected signals (tool errors, empty responses, Rule-1 leaks)
   * flow through a separate server-side write path — not this mutation.
   */
  submitAssistantFeedback: SubmitAssistantFeedbackResponse
  updateAddPersonToFieldContextResponses: UpdateAddPersonToFieldContextResponsesMutationResponse
  updateAddSpaceMemberResponses: UpdateAddSpaceMemberResponsesMutationResponse
  updateCarePulses: UpdateCarePulsesMutationResponse
  updateChatbotResponses: UpdateChatbotResponsesMutationResponse
  updateCoreValuePulses: UpdateCoreValuePulsesMutationResponse
  updateCreateLogResponses: UpdateCreateLogResponsesMutationResponse
  updateCreatePersonConnectionResponses: UpdateCreatePersonConnectionResponsesMutationResponse
  updateDeleteDocumentResponses: UpdateDeleteDocumentResponsesMutationResponse
  updateDeletePersonConnectionResponses: UpdateDeletePersonConnectionResponsesMutationResponse
  updateDocumentIngestThreads: UpdateDocumentIngestThreadsMutationResponse
  updateDocuments: UpdateDocumentsMutationResponse
  updateFieldContexts: UpdateFieldContextsMutationResponse
  updateGoalPulses: UpdateGoalPulsesMutationResponse
  updateIngestDocumentResponses: UpdateIngestDocumentResponsesMutationResponse
  updateLogs: UpdateLogsMutationResponse
  updateMarkNotificationResponses: UpdateMarkNotificationResponsesMutationResponse
  updateMeSpaces: UpdateMeSpacesMutationResponse
  updatePeople: UpdatePeopleMutationResponse
  /**
   * Update an existing person-to-person connection.
   * Updates the why and interests metadata for a CONNECTED_TO relationship.
   */
  updatePersonConnection: UpdatePersonConnectionResponse
  updatePersonConnectionEdges: UpdatePersonConnectionEdgesMutationResponse
  /**
   * Edit a PersonPulse (a non-user :Person:PersonPulse) — its identity, its
   * relational `description` note, and the caller's relationship to it.
   *
   * Authorization (enforced server-side, NOT via @authorization since this is a
   * custom resolver): the target must NOT carry the User label, and the caller
   * must own or be a member of a Space that has a FieldContext attached to this
   * person. This is the same reach used by the assistant's create_person, so
   * create and edit are symmetric. Editing a real User's node is rejected — that
   * flows through the self-gated updatePeople instead.
   *
   * Only non-null arguments are applied. `relationshipWhy` MERGEs/updates a
   * CONNECTED_TO edge from the caller to the person (empty string clears the why).
   */
  updatePersonPulse: UpdatePersonPulseResponse
  updateRemoveSpaceMemberResponses: UpdateRemoveSpaceMemberResponsesMutationResponse
  updateResonanceLinks: UpdateResonanceLinksMutationResponse
  updateResourcePulses: UpdateResourcePulsesMutationResponse
  /**
   * Update a space member's role.
   * Only the space owner or members with ADMIN role can change roles.
   */
  updateSpaceMemberRole: UpdateSpaceMemberRoleResponse
  updateSpaceMemberships: UpdateSpaceMembershipsMutationResponse
  updateStoryPulses: UpdateStoryPulsesMutationResponse
  updateSubmitAssistantFeedbackResponses: UpdateSubmitAssistantFeedbackResponsesMutationResponse
  updateUpdatePersonConnectionResponses: UpdateUpdatePersonConnectionResponsesMutationResponse
  updateUpdatePersonPulseResponses: UpdateUpdatePersonPulseResponsesMutationResponse
  updateUpdateSpaceMemberRoleResponses: UpdateUpdateSpaceMemberRoleResponsesMutationResponse
  updateUpdateUserAiResponses: UpdateUpdateUserAiResponsesMutationResponse
  /**
   * Update AI functionality preferences for a user.
   * Users can enable or disable AI features in the application.
   */
  updateUserAI: UpdateUserAiResponse
  updateUsers: UpdateUsersMutationResponse
  updateWeSpaces: UpdateWeSpacesMutationResponse
}

